custom_fields.subtitle:
[[[
  const vacuum = states['vacuum.vaccuminator'];
  const battery = states['sensor.vaccuminator_battery_level']?.state;
  const labels = {
    cleaning: 'A limpar',
    paused: 'Em pausa',
    returning: 'A regressar à base',
    docked: 'Na base',
    idle: 'Pronto',
    unavailable: 'Indisponível',
    unknown: 'Desconhecido'
  };
  const status = labels[vacuum?.state] || vacuum?.state || 'Indisponível';
  return battery && !['unknown', 'unavailable'].includes(battery)
    ? `${status} · ${battery}%`
    : status;
]]]

tap_action.service:
[[[
  const st = states['vacuum.vaccuminator'].state;
  if (st === 'cleaning') return 'vacuum.pause';
  if (st === 'returning') return 'homeassistant.update_entity';
  if (states['input_boolean.mod_total_or_area'].state === 'on')
    return 'script.turn_on';
  else
    return 'vacuum.start';
]]]

tap_action.service_data:
[[[
  const st = states['vacuum.vaccuminator'].state;
  if (st === 'cleaning' || st === 'returning') {
    return { entity_id: 'vacuum.vaccuminator' };
  }
  if (states['input_boolean.mod_total_or_area'].state === 'on') {
    return { entity_id: 'script.vaccuminator_segments' };
  } else {
    return { entity_id: 'vacuum.vaccuminator' };
  }
]]]

card.border:
[[[
  const st = states['vacuum.vaccuminator'].state;
  if (st === 'cleaning') return '1px solid rgba(255, 204, 0, 0.25)';
  if (st === 'returning') return '1px solid rgba(255,255,255,0.08)';
  return '1px solid rgba(76, 217, 100, 0.25)';
]]]

card.box-shadow:
[[[
  const st = states['vacuum.vaccuminator'].state;
  if (st === 'cleaning') return '0 0 12px rgba(255, 204, 0, 0.15)';
  if (st === 'returning') return 'none';
  return '0 0 12px rgba(76, 217, 100, 0.15)';
]]]

icon.color:
[[[
  const st = states['vacuum.vaccuminator'].state;
  if (st === 'cleaning') return '#ffcc00';
  if (st === 'returning') return 'rgba(255,255,255,0.25)';
  return '#4cd964';
]]]

card.border:
[[[
  const canStop = !['idle','docked'].includes(states['vacuum.vaccuminator'].state);
  return canStop ? '1px solid rgba(255, 59, 48, 0.25)' : '1px solid rgba(255,255,255,0.08)';
]]]

